/**
 * The series steps "acme" ADDED, readable under ANY system: the active system's own value when it
 * has the step, else the value "acme" gives it — reported once in development builds, never thrown.
 */
export const acmeSteps = {
  motion: {
    spring: {
      expressive: {
        bouncy: (system: TanreiSystem): TanreiSpring => seriesStep<TanreiSpring>(system.motion.spring.expressive, "bouncy", {
          damping: 0.4,
          duration: 500,
          easing: [0.38, 1.21, 0.22, 1],
          stiffness: 500,
        }, "motion.spring.expressive"),
      },
      standard: {
        bouncy: (system: TanreiSystem): TanreiSpring => seriesStep<TanreiSpring>(system.motion.spring.standard, "bouncy", {
          damping: 0.5,
          duration: 500,
          easing: [0.27, 1.06, 0.18, 1],
          stiffness: 700,
        }, "motion.spring.standard"),
      },
    },
  },
  space: {
    space1200: (system: TanreiSystem): number => seriesStep<number>(system.space, "space1200", 96, "space"),
  },
} as const;

/** The "acme" layer's own tokens (`acme.*`). They are not part of `TanreiSystem`: read them next to it. */
export interface AcmeTokens {
  readonly comp: {
    readonly rating: {
      readonly gap: number;
      readonly star: {
        readonly color: TanreiPaint;
        readonly size: number;
      };
    };
  };
}

/** Colors are paints (evaluate with `useTanrei().paint()`); type styles and elevations name a step of the system. */
export const acmeTokens = {
  comp: {
    rating: {
      gap: 4,
      star: {
        color: { kind: "role", role: "warning" },
        size: 20,
      },
    },
  },
} as const satisfies AcmeTokens;
